extra_head_css:
.model-selector { margin: 16px 0; padding: 12px 16px; background: var(--surface); border-radius: 12px; border: 1px solid var(--border); }
    .model-selector label { display: block; font-size: 12px; font-weight: 600; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
    .model-options { display: flex; gap: 8px; flex-wrap: wrap; }
    .model-btn { flex: 1; min-width: 80px; padding: 8px 12px; border: 1.5px solid var(--border); border-radius: 8px; background: transparent; color: var(--text); font-size: 13px; font-weight: 500; cursor: pointer; transition: all 0.2s; white-space: nowrap; }
    .model-btn:hover { border-color: var(--primary); color: var(--primary); }
    .model-btn.active { background: var(--primary); border-color: var(--primary); color: #fff; }
    .model-btn:disabled { opacity: 0.5; cursor: not-allowed; }
    .model-note { margin-top: 10px; font-size: 12px; color: var(--text-secondary); font-style: italic; }
    .model-note::before { content: '💡 '; font-style: normal; }
    @media (max-width: 480px) { .model-options { flex-direction: column; } }
